<map version="1.0.1"><node CREATED="1747229310350" ID="ID_root" MODIFIED="1747229310350" TEXT="Day02_basic2"><node CREATED="1747229310350" ID="ID_09f5355a22d084dd" POSITION="right" MODIFIED="1747229310350" TEXT="vs调试"><node CREATED="1747229310350" ID="ID_4c777070584e1a59" MODIFIED="1747229310350" TEXT="调试代码的含义"><node CREATED="1747229310350" ID="ID_88f693c5c457b573" MODIFIED="1747229310350" TEXT="前提：代码要能跑起来"><node CREATED="1747229310350" ID="ID_1814a796d9d113ab" MODIFIED="1747229310350" TEXT="要先处理掉编译错误、链接错误。&amp;nbsp;"><node CREATED="1747229310350" ID="ID_146b6cdabf4fc6b3" MODIFIED="1747229310350" TEXT="编译错误一般是因为语法问题，所以检查一下语法。&amp;lt;br&amp;gt;C***"></node><node CREATED="1747229310350" ID="ID_0569fa79fa2304c3" MODIFIED="1747229310350" TEXT="链接错误，一般是找不到函数的函数体。&amp;nbsp;&amp;lt;br&amp;gt;"></node></node></node><node CREATED="1747229310350" ID="ID_dff88142c9ba9a09" MODIFIED="1747229310350" TEXT="程序员自己心里要有预期。&amp;nbsp;调试其实就是一个信息比对的任务。&amp;nbsp;"></node></node><node CREATED="1747229310350" ID="ID_9eda1437c27f0e89" MODIFIED="1747229310350" TEXT="打断点"></node><node CREATED="1747229310350" ID="ID_42148e115702b270" MODIFIED="1747229310350" TEXT="跳到下一个断点"></node><node CREATED="1747229310350" ID="ID_c42648e717fd41c8" MODIFIED="1747229310350" TEXT="逐过程（波浪线箭头）：&amp;nbsp;碰到自己写的函数会进去"></node><node CREATED="1747229310350" ID="ID_906bdb3081e5c365" MODIFIED="1747229310350" TEXT="逐语句(向下箭头)：&amp;nbsp;碰到函数会跳过。直接执行结束"></node><node CREATED="1747229310350" ID="ID_c02f65ebe3e1bfb5" MODIFIED="1747229310350" TEXT="调试需要多练习"><node CREATED="1747229310350" ID="ID_15d6f3a2a435613e" MODIFIED="1747229310350" TEXT="技巧1：&amp;nbsp;如何知道打断点的位置。&amp;lt;br&amp;gt;眼睛扫一下，哪里容易出错，就往哪里打断点"></node><node CREATED="1747229310350" ID="ID_f58b53897cec5db5" MODIFIED="1747229310350" TEXT="技巧2：程序崩溃了，怎么知道在哪出了问题&amp;lt;br&amp;gt;可以注释一下，如果注释了之后，就不出问题了。可能问题就在这里"></node><node CREATED="1747229310350" ID="ID_653448aae83b9547" MODIFIED="1747229310350" TEXT="技巧3：&amp;nbsp;建议大家根据数据的流向来分析问题。&amp;nbsp;这个数据从哪来，被谁改过。&amp;nbsp;&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229310350" ID="ID_199b911dfc5faa18" MODIFIED="1747229310350" TEXT="如果调试--窗口看不到内存。&amp;nbsp;这时候先将程序运行起来。然后才能看到"></node></node><node CREATED="1747229310350" ID="ID_4aa0033b05396d7a" POSITION="right" MODIFIED="1747229310350" TEXT="标准输入输出"><node CREATED="1747229310350" ID="ID_8934238fba395cde" MODIFIED="1747229310350" TEXT="printf"><node CREATED="1747229310350" ID="ID_9b930d94b3c3fa46" MODIFIED="1747229310350" TEXT="标准输出。&amp;nbsp;输出到屏幕。&amp;nbsp;"></node><node CREATED="1747229310350" ID="ID_7920af18225aaeb7" MODIFIED="1747229310350" TEXT="printf是有一个缓冲区的，也就是输出的内容，&amp;lt;br&amp;gt;会先进入缓冲区（内存上），&amp;nbsp;等到合适的时机，再往外刷"></node><node CREATED="1747229310350" ID="ID_955c7e41060592ac" MODIFIED="1747229310350" TEXT="缓冲区的几个分类"><node CREATED="1747229310350" ID="ID_53cebf47b7a1fc6e" MODIFIED="1747229310350" TEXT="满缓冲区"><node CREATED="1747229310350" ID="ID_cd227682ef3cce77" MODIFIED="1747229310350" TEXT="当缓冲区满的时候，数据才会刷新到目的地。&amp;nbsp;"></node></node><node CREATED="1747229310350" ID="ID_bca07a7b094a42a8" MODIFIED="1747229310350" TEXT="行缓冲区"><node CREATED="1747229310350" ID="ID_e60afa9b3f001abf" MODIFIED="1747229310350" TEXT="printf就是行缓冲区。&amp;lt;br&amp;gt;如果在不影响业务逻辑下，建议printf加 \n"></node></node><node CREATED="1747229310350" ID="ID_a5333b3d17d4a17f" MODIFIED="1747229310350" TEXT="无缓冲区"><node CREATED="1747229310350" ID="ID_f8c34ae981d86c57" MODIFIED="1747229310350" TEXT="stderr就是无缓冲区"></node></node></node><node CREATED="1747229310350" ID="ID_f431b8f1d536893d" MODIFIED="1747229310350" TEXT="面试题：缓冲区的作用？"><node CREATED="1747229310350" ID="ID_7d618765619ee9c7" MODIFIED="1747229310350" TEXT="平衡速度的差异。&amp;nbsp;一方速度快，一方速度慢，可以加缓冲区平衡两者的速度差异。&amp;nbsp;"></node></node><node CREATED="1747229310350" ID="ID_78528d2b8e82312f" MODIFIED="1747229310350" TEXT="上课讲的比较多的是重点。&amp;nbsp;另外有一些比较简单的，大家能自己看懂，就没有使劲讲"></node></node><node CREATED="1747229310350" ID="ID_3fa19b31a7a677f1" MODIFIED="1747229310350" TEXT="scanf"><node CREATED="1747229310350" ID="ID_c3b9a135d5f5555c" MODIFIED="1747229310350" TEXT="scanf就是从键盘做输入"></node><node CREATED="1747229310350" ID="ID_823b71b108a169de" MODIFIED="1747229310350" TEXT="scanf也有缓冲区，也就是我们输入的数据，会先进入一个叫做 stdin的输入缓冲区中。&amp;nbsp;然后CPU是从这块读数据的"></node><node CREATED="1747229310350" ID="ID_183def7255b6baf5" MODIFIED="1747229310350" TEXT="工作原理比较重要"><node CREATED="1747229310350" ID="ID_81d50431fec4e938" MODIFIED="1747229310350" TEXT="// scanf函数会从左到右依次匹配格式字符串中的每一项：&amp;lt;br&amp;gt;// 如果匹配数据项成功，那么scanf函数会继续处理格式串的剩余部分；&amp;lt;br&amp;gt;// 如果匹配不成功，那么scanf函数将不再处理格式串的剩余部分，而会立刻返回。"></node></node><node CREATED="1747229310350" ID="ID_24aecb73f6181045" MODIFIED="1747229310350" TEXT="录入字符这块比较特殊&amp;lt;br&amp;gt;要注意&amp;nbsp;空格和换行符的影响&amp;lt;br&amp;gt;解决方式，建议在%c 前面加上一个空格。 可以匹配n个空格。 也可以匹配换行符这种"></node></node><node CREATED="1747229310350" ID="ID_1935523e8610cd4f" MODIFIED="1747229310350" TEXT="fprintf / fscanf&amp;lt;br&amp;gt;sprintf / sscanf"><node CREATED="1747229310350" ID="ID_0154120ea1ec8a8a" MODIFIED="1747229310350" TEXT="族函数"></node><node CREATED="1747229310350" ID="ID_310b7e1a9ed659c2" MODIFIED="1747229310350" TEXT="printf是往屏幕做输出的。&amp;nbsp;&amp;lt;br&amp;gt;fprintf&amp;nbsp;也是做输出的。&amp;nbsp;输出目的地是文件。&amp;nbsp;&amp;lt;br&amp;gt;sprintf&amp;nbsp;也是做输出。&amp;nbsp;输出的目的地是字符串"><node CREATED="1747229310350" ID="ID_d82a8651fa27a86b" MODIFIED="1747229310350" TEXT="fprintf(fp, &amp;quot;%d %d&amp;quot;, num, num2);"></node><node CREATED="1747229310350" ID="ID_4367198000441920" MODIFIED="1747229310350" TEXT="sprintf(arr, &amp;quot;%d %d&amp;quot;, num1, num2);"></node></node><node CREATED="1747229310350" ID="ID_42a088e429256317" MODIFIED="1747229310350" TEXT="scanf&amp;nbsp;做输入的。&amp;nbsp;从键盘做输入&amp;lt;br&amp;gt;fscanf&amp;nbsp;做输入的。&amp;nbsp;从文件中做输入&amp;lt;br&amp;gt;sscanf&amp;nbsp;做输入的。&amp;nbsp;从字符串中做输入"></node><node CREATED="1747229310350" ID="ID_3123590ae3b5ed91" MODIFIED="1747229310350" TEXT="一定要清楚的知道printf是做输出的。&amp;nbsp; fprintf/sprintf&amp;nbsp;都是输出"></node><node CREATED="1747229310350" ID="ID_54da287a1ed1cb86" MODIFIED="1747229310350" TEXT="scanf是做输入的，sscanf fscanf&amp;nbsp;都是输入，只是数据的来源不同"></node></node><node CREATED="1747229310350" ID="ID_21e7c25370de2bad" MODIFIED="1747229310350" TEXT="使用的时候printf和scanf的使用，不要混淆了"><node CREATED="1747229310350" ID="ID_4cce41e3e8404177" MODIFIED="1747229310350" TEXT="printf(&amp;quot;%d, %d\n&amp;quot;, &amp;amp;i, &amp;amp;j); /*** WRONG ***/"></node><node CREATED="1747229310350" ID="ID_02bc429948d4f562" MODIFIED="1747229310350" TEXT="scanf(&amp;quot;%d, %d&amp;quot;, &amp;amp;a, &amp;amp;b);&amp;nbsp; &amp;nbsp; // 这样写输入的数据必须是 &amp;quot;10, 20&amp;quot;格式的&amp;lt;br&amp;gt;scanf(&amp;quot;%d\n&amp;quot;, &amp;amp;a);&amp;nbsp; &amp;nbsp; &amp;nbsp; // 错误的添加换行"></node></node><node CREATED="1747229310350" ID="ID_f064067e98f669a0" MODIFIED="1747229310350" TEXT="练习"><node CREATED="1747229310350" ID="ID_be387b2548307b0f" MODIFIED="1747229310350" TEXT="分子分母的输入，两个分数相加"></node><node CREATED="1747229310350" ID="ID_65c72154b3ef9799" MODIFIED="1747229310350" TEXT="假设今天需要你化简，&amp;lt;br&amp;gt;你不知道化简的算法。&amp;nbsp;怎么办？"><node CREATED="1747229310350" ID="ID_62dd7dff85840017" MODIFIED="1747229310350" TEXT="1.搜索引擎搜。&amp;nbsp;&amp;lt;br&amp;gt;技巧就是：&amp;nbsp;想一下关键词，然后关键词空格&amp;nbsp;全输入进去&amp;lt;br&amp;gt;不要用百度。 bing.com"></node><node CREATED="1747229310350" ID="ID_18d9d9f185308128" MODIFIED="1747229310350" TEXT="2.可以问一下AI。&amp;lt;br&amp;gt;技巧就是：&amp;nbsp;你需要清晰的说出你的需求。&amp;nbsp;"><node CREATED="1747229310350" ID="ID_9b0e5ce55a2af01c" MODIFIED="1747229310350" TEXT="现在，我需要在C语言中，从键盘录入两个分数。&amp;nbsp;&amp;lt;br&amp;gt;紧接着将这两个分数求和。&amp;lt;br&amp;gt;求和之后，帮我化简一下。"></node><node CREATED="1747229310350" ID="ID_8435eb0ded084beb" MODIFIED="1747229310350" TEXT="一定要学会和AI沟通"></node></node></node></node></node><node CREATED="1747229310350" ID="ID_297148c2b0206f54" POSITION="right" MODIFIED="1747229310350" TEXT="基本数据类型"><node CREATED="1747229310350" ID="ID_b7b5319035a59ce6" MODIFIED="1747229310350" TEXT="sizeof运算符&amp;lt;br&amp;gt;"><node CREATED="1747229310350" ID="ID_2557cd822bf05cbf" MODIFIED="1747229310350" TEXT="可以用来计算一个类型、变量占多大空间。"></node><node CREATED="1747229310350" ID="ID_36907ef632c80cf7" MODIFIED="1747229310350" TEXT="sizeof(int)&amp;lt;br&amp;gt;sizeof(num)&amp;lt;br&amp;gt;sizeof(1+2)"></node><node CREATED="1747229310350" ID="ID_1467c616a76ab257" MODIFIED="1747229310350" TEXT="返回值是一个size_t"><node CREATED="1747229310350" ID="ID_18ed97df2283d012" MODIFIED="1747229310350" TEXT="这个是一个和系统位数相关的，无符号的整数&amp;lt;br&amp;gt;"></node><node CREATED="1747229310350" ID="ID_2aff770ab39382ff" MODIFIED="1747229310350" TEXT="这个其实叫做类型别名，就是另外取的一个名字，小名"></node></node></node><node CREATED="1747229310350" ID="ID_b627a91090f755a5" MODIFIED="1747229310350" TEXT="整型"><node CREATED="1747229310350" ID="ID_78962f8b1208bc45" MODIFIED="1747229310350" TEXT="整体分两类：有符号、无符号"><node CREATED="1747229310350" ID="ID_32e9e43a1d68e866" MODIFIED="1747229310350" TEXT="有符号和无符号的区别得会"></node></node><node CREATED="1747229310350" ID="ID_881b87359b68a6cd" MODIFIED="1747229310350" TEXT="short int long long long"><node CREATED="1747229310350" ID="ID_32178144eaf047f3" MODIFIED="1747229310350" TEXT="注意事项：不要直接认为int直接一定是4个字节。在有一些环境中，可能只有2个字节"></node><node CREATED="1747229310350" ID="ID_cad4ed508740efbc" MODIFIED="1747229310350" TEXT="C标准规定了最小的字节。还规定了大小顺序"></node><node CREATED="1747229310350" ID="ID_b3e5a1d6e71c4bbe" MODIFIED="1747229310350" TEXT="一般使用int居多"></node><node CREATED="1747229310350" ID="ID_6055788e7e06f183" MODIFIED="1747229310350" TEXT="注意1：在写一个字面值long类型的常量时，一定是L。"><node CREATED="1747229310350" ID="ID_4949d7c39f55c735" MODIFIED="1747229310350" TEXT="不然这里可能出现一个误解，就是误认为这个是1."></node><node CREATED="1747229310350" ID="ID_337ec367a771af1d" MODIFIED="1747229310350" TEXT="101&amp;lt;br&amp;gt;10l&amp;lt;br&amp;gt;10L"></node></node><node CREATED="1747229310350" ID="ID_ab32761e451b9693" MODIFIED="1747229310350" TEXT="注意2：无符号数的时候时需要注意"><node CREATED="1747229310350" ID="ID_0df913583c1013e4" MODIFIED="1747229310350" TEXT="使用无符号数和有符号数比较的时候，可能会出现代码的实际和我们的预期不一致"></node><node CREATED="1747229310350" ID="ID_21c474a269c6be5e" MODIFIED="1747229310350" TEXT="建议：一般使用有符号数。除非迫不得已，不然不要使用无符号数"></node><node CREATED="1747229310350" ID="ID_3c1a246e1921b7ff" MODIFIED="1747229310350" TEXT="如果确实要使用无符号数，不要和有符号数混用"></node></node></node></node><node CREATED="1747229310350" ID="ID_c5a7ac0e94599090" MODIFIED="1747229310350" TEXT="浮点型"><node CREATED="1747229310350" ID="ID_b036a54ab31abb4d" MODIFIED="1747229310350" TEXT="知道浮点数的不精确是绝对的就可以了"></node><node CREATED="1747229310350" ID="ID_cb109983768382ba" MODIFIED="1747229310350" TEXT="它是使用的科学计数法，所以存储的范围比较大"><node CREATED="1747229310350" ID="ID_f331e2607ae8fbb5" MODIFIED="1747229310350" TEXT="float&amp;nbsp;的范围要比 long long大的多。&amp;nbsp;"></node></node><node CREATED="1747229310350" ID="ID_45103e566facacd4" MODIFIED="1747229310350" TEXT="float占4个字节；&amp;nbsp;double占8个字节"></node><node CREATED="1747229310350" ID="ID_a5087518ac0c90c7" MODIFIED="1747229310350" TEXT="扩展：如果不想有精度损失问题，这时候，可以使用字符串来存储这些数据。&amp;nbsp;&amp;lt;br&amp;gt;字符串后面会具体讲"></node></node><node CREATED="1747229310350" ID="ID_328f622afed27b9f" MODIFIED="1747229310350" TEXT="字符型"><node CREATED="1747229310350" ID="ID_e224af189fa7b6b5" MODIFIED="1747229310350" TEXT="字符型的底层，其实也是使用的整型来存数据"></node><node CREATED="1747229310350" ID="ID_85f473b8f99a41b6" MODIFIED="1747229310350" TEXT="计算机是怎么存储这些字符的"><node CREATED="1747229310350" ID="ID_4ea3c9bdf3e623a3" MODIFIED="1747229310350" TEXT="其实是使用的一个编码表，将所有的字符弄一个对应关系，现在需要存储这个字符，就等价于要存储这个数。&amp;lt;br&amp;gt;下次见到这个数，就转换过来"></node><node CREATED="1747229310350" ID="ID_1b87c49e8c0513a3" MODIFIED="1747229310350" TEXT="比如， a对应的就是97。现在要存储a，就把97存上。&amp;lt;br&amp;gt;下次取出来是97，那这就是a。"></node><node CREATED="1747229310350" ID="ID_aac04f244d065cfd" MODIFIED="1747229310350" TEXT="常见编码表"><node CREATED="1747229310350" ID="ID_eba19f42ef0bb6e9" MODIFIED="1747229310350" TEXT="ASCII：&amp;nbsp;美国标准委员会指定的编码表，使用1个字节来编码。所以能存储的字符比较有限。只有英文&amp;lt;br&amp;gt;"></node><node CREATED="1747229310350" ID="ID_31aa6d57f726e378" MODIFIED="1747229310350" TEXT="GBK：&amp;nbsp;中国自己定义的编码表，里面有中文的编码&amp;lt;br&amp;gt;"></node><node CREATED="1747229310350" ID="ID_e3737b64857e4bd7" MODIFIED="1747229310350" TEXT="UTF-8:&amp;nbsp;是一个国际标准的编码表，兼容ASCII，里面有有中文、日文、韩文等多种语言"></node></node></node><node CREATED="1747229310350" ID="ID_2f36b8cb0029d929" MODIFIED="1747229310350" TEXT="读写字符"><node CREATED="1747229310350" ID="ID_4b83ffc25013922a" MODIFIED="1747229310350" TEXT="scanf(&amp;quot;%c&amp;quot;, &amp;amp;ch);&amp;lt;br&amp;gt;printf(&amp;quot;%c&amp;quot;, ch);"></node><node CREATED="1747229310350" ID="ID_eea80baaaa05b056" MODIFIED="1747229310350" TEXT="putchar&amp;nbsp;&amp;lt;br&amp;gt;getchar"></node><node CREATED="1747229310350" ID="ID_7259960a969d3ae7" MODIFIED="1747229310350" TEXT="如果想一行一行的读取，&amp;lt;br&amp;gt;这时候可以使用getchar&amp;nbsp;完成。&amp;nbsp;"><node CREATED="1747229310350" ID="ID_4c76502baa44b6df" MODIFIED="1747229310350" TEXT="int ch;&amp;lt;br&amp;gt;while((ch = getchar()) != &amp;apos;\n&amp;apos;){&amp;lt;br&amp;gt;&amp;nbsp; &amp;nbsp; //&amp;nbsp;里面单独处理一个字符&amp;lt;br&amp;gt;}"></node><node CREATED="1747229310350" ID="ID_70cba4e104d85d64" MODIFIED="1747229310350" TEXT="清空缓冲区的习惯写法&amp;lt;br&amp;gt;int ch;&amp;lt;br&amp;gt;while((ch = getchar()) != &amp;apos;\n&amp;apos;);&amp;lt;br&amp;gt;"></node></node></node></node><node CREATED="1747229310350" ID="ID_f42ca05a0f3368e4" MODIFIED="1747229310350" TEXT="类型转换"><node CREATED="1747229310350" ID="ID_10ebd4315f14302d" MODIFIED="1747229310350" TEXT="类型转换分为：隐式类型转换、强制类型转换"></node><node CREATED="1747229310350" ID="ID_2006adbe6167a858" MODIFIED="1747229310350" TEXT="隐式类型转换：&amp;nbsp;这一过程是自动完成的，如果赋值表达式右边值的类型和左边变量的类型不匹配，&amp;lt;br&amp;gt;则赋值表达式右边值的类型会被隐式转换为左边变量的类型&amp;lt;br&amp;gt;"><node CREATED="1747229310350" ID="ID_223a77ae7dd6c069" MODIFIED="1747229310350" TEXT="int a = 10.1;&amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp;// 隐式类型转换，数据截断&amp;lt;br&amp;gt;char b = 97.9f;&amp;nbsp; &amp;nbsp; &amp;nbsp;// 隐式类型转换，数据截断&amp;lt;br&amp;gt;double c = 0.1;&amp;lt;br&amp;gt;float d = c;&amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; // 隐式类型转换，数据精度丢失"></node><node CREATED="1747229310350" ID="ID_22cf6c619f795af6" MODIFIED="1747229310350" TEXT="转换等级了解一下，基本就是根据这个类型能表示的范围，&amp;nbsp;整数不用说，基本就是按照字节数&amp;lt;br&amp;gt;float虽然是4字节，但是是科学计数法，所以范围要比整数大&amp;lt;br&amp;gt;整数&amp;nbsp; &amp;lt;&amp;nbsp; float &amp;lt; double&amp;nbsp;&amp;lt;br&amp;gt;哪个桶更大，更能装&amp;lt;br&amp;gt;"></node><node CREATED="1747229310350" ID="ID_fa74ac3e92701f7b" MODIFIED="1747229310350" TEXT="整数提升：&amp;nbsp;当表达式中仅有int以及int以下等级的类型参与时，表达式的结果一律是int(或者unsigned int)&amp;lt;br&amp;gt;"></node><node CREATED="1747229310350" ID="ID_44957362f1623855" MODIFIED="1747229310350" TEXT="算术转换：&amp;nbsp;简单说，表达式中有一个大的范围的值，这个表达式的结果就是大的范围&amp;lt;br&amp;gt;比如里面有long，&amp;nbsp;最后计算的结果就是long&amp;lt;br&amp;gt;int&amp;nbsp; + long&amp;nbsp; ==&amp;gt;&amp;nbsp;结果是long&amp;nbsp;&amp;lt;br&amp;gt;int + double&amp;nbsp; &amp;nbsp;===&amp;gt; double&amp;lt;br&amp;gt;long long + float ===&amp;gt;&amp;nbsp; float"></node></node><node CREATED="1747229310350" ID="ID_6b1b31fec184b8dc" MODIFIED="1747229310350" TEXT="强制类型转换：在表达式前面加上一个转换类型的符号。&amp;nbsp;&amp;lt;br&amp;gt;(type_name) expression&amp;lt;br&amp;gt;char ch = 18;"></node></node><node CREATED="1747229310350" ID="ID_987e40331179f7e6" MODIFIED="1747229310350" TEXT="类型别名"><node CREATED="1747229310350" ID="ID_9e2e7273255c5814" MODIFIED="1747229310350" TEXT="我们可以使用typedef关键字用于为现有的数据类型创建新的名称，即类型别名。"></node><node CREATED="1747229310350" ID="ID_f4727d43f2f95b90" MODIFIED="1747229310350" TEXT="语法&amp;lt;br&amp;gt;typedef 现有类型的名字 别名;&amp;lt;br&amp;gt;typedef int DataType;"></node><node CREATED="1747229310350" ID="ID_081117909c77423e" MODIFIED="1747229310350" TEXT="好处"><node CREATED="1747229310350" ID="ID_30ac9e94f51fc64a" MODIFIED="1747229310350" TEXT="提升代码的可读性&amp;lt;br&amp;gt;"><node CREATED="1747229310350" ID="ID_1424de68b9aa7b6e" MODIFIED="1747229310350" TEXT="比如链表中，是由一个一个的结点构成的。我们可以给结点取名Node。&amp;lt;br&amp;gt;可以提升代码可读性&amp;lt;br&amp;gt;栈帧。 StackFrame"></node></node><node CREATED="1747229310350" ID="ID_6c4618516f26e823" MODIFIED="1747229310350" TEXT="提升代码的扩展性"><node CREATED="1747229310350" ID="ID_217f847f936aeddf" MODIFIED="1747229310350" TEXT="typedef&amp;nbsp; int DataType;&amp;lt;br&amp;gt;"></node><node CREATED="1747229310350" ID="ID_9805c9f6e098281d" MODIFIED="1747229310350" TEXT="后续可以在不同的环境下，只用改一行代码。&amp;nbsp;&amp;lt;br&amp;gt;比如，在平常环境下，使用int就可以。&amp;nbsp;&amp;lt;br&amp;gt;在一些int只有2字节的环境中，可以将int改成 long 。即 typedef long DataType"></node></node><node CREATED="1747229310350" ID="ID_f5d8ad2cee52aff5" MODIFIED="1747229310350" TEXT="提升代码的跨平台性移植性"></node></node><node CREATED="1747229310350" ID="ID_77d0f921b17650c6" MODIFIED="1747229310350" TEXT="关于类型别名，官方的命名"><node CREATED="1747229310350" ID="ID_e39e9b787e211f10" MODIFIED="1747229310350" TEXT="它会为类型别名取一个名字。&amp;nbsp;一般是以_t结尾。&amp;lt;br&amp;gt;size_t:&amp;nbsp;与环境和编译器相关的无符号整数。&amp;nbsp;一般用它来存储长度，个数，大小&amp;lt;br&amp;gt;int8_t:&amp;lt;br&amp;gt;int16_t:&amp;lt;br&amp;gt;int32_t:&amp;nbsp;有什么好处，就是在任何环境下都可以使用，而且长度是固定的&amp;lt;br&amp;gt;uint32_t"></node><node CREATED="1747229310350" ID="ID_907bae19a1547628" MODIFIED="1747229310350" TEXT="int32_t。如果发现在一台电脑上，不是32位，咋办？&amp;lt;br&amp;gt;&amp;nbsp;int"></node></node></node><node CREATED="1747229310350" ID="ID_fca6519533b87f20" MODIFIED="1747229310350" TEXT="布尔值"><node CREATED="1747229310350" ID="ID_f0912a81c9f4bbc0" MODIFIED="1747229310350" TEXT="注意：&amp;nbsp;在C语言中，布尔值不是一个内置数据类型。&amp;lt;br&amp;gt;bool flag;"></node><node CREATED="1747229310350" ID="ID_1e23e288a0a613a6" MODIFIED="1747229310350" TEXT="需要引入一个头文件 stdbool.h"></node><node CREATED="1747229310350" ID="ID_ea6a58d1e9302255" MODIFIED="1747229310350" TEXT="需要知道哪些值为真"><node CREATED="1747229310350" ID="ID_64623dd901cd3e9b" MODIFIED="1747229310350" TEXT="为了表示布尔值C语言规定：&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;任何非零值都被视为true(真)&amp;lt;br&amp;gt;任何零值都被视为false(假)&amp;lt;br&amp;gt;"></node></node></node></node><node CREATED="1747229310350" ID="ID_6aba9437eea0ccb0" POSITION="right" MODIFIED="1747229310350" TEXT="优先级和结合性"><node CREATED="1747229310350" ID="ID_f23819c8e8489714" MODIFIED="1747229310350" TEXT="主要作用和副作用"><node CREATED="1747229310350" ID="ID_d6b17bdb0deffc21" MODIFIED="1747229310350" TEXT="主要作用：&amp;nbsp;就是一个表达式的结果。&amp;nbsp;我们关注主要主要作用，主要是因为。&amp;nbsp;&amp;lt;br&amp;gt;在大表达式中，是小表达式的主要作用在起作用"></node><node CREATED="1747229310350" ID="ID_837eb15d2c9b7d3f" MODIFIED="1747229310350" TEXT="副作用：&amp;nbsp;除了主要作用以外的作用。&amp;nbsp;比如，修改了变量的值。&amp;nbsp;&amp;lt;br&amp;gt;比如，一些IO操作，这时候也是副作用。&amp;nbsp;"></node><node CREATED="1747229310350" ID="ID_84fccd984a983a17" MODIFIED="1747229310350" TEXT="理解主要作用，和副作用可以帮助我们理解更准确的大的表达式。&amp;nbsp;"></node></node><node CREATED="1747229310350" ID="ID_bbe0f614ab65e6c8" MODIFIED="1747229310350" TEXT="优先级和结合性"><node CREATED="1747229310350" ID="ID_af62d981a1855959" MODIFIED="1747229310350" TEXT="优先级就是一个运算符的优先顺序。结合性就是在优先级相同的时候，怎么结合"></node><node CREATED="1747229310350" ID="ID_b8359a25f5a95c1e" MODIFIED="1747229310350" TEXT="a+b-c:&amp;nbsp;这个+和-的优先级相同，这时候就看结合性"></node><node CREATED="1747229310350" ID="ID_4027f75afcb14516" MODIFIED="1747229310350" TEXT="a*b-c+d/2:&amp;nbsp;&amp;nbsp;"></node><node CREATED="1747229310350" ID="ID_618f1821ce73dc80" MODIFIED="1747229310350" TEXT="注意一些比较难的表达式"><node CREATED="1747229310350" ID="ID_feb516ee8e8feb47" MODIFIED="1747229310350" TEXT="(b-a&amp;gt;&amp;gt;1) + a"></node><node CREATED="1747229310350" ID="ID_96f48343e7b4a6ab" MODIFIED="1747229310350" TEXT="*p++"></node></node></node><node CREATED="1747229310350" ID="ID_0918e49a9441fe72" MODIFIED="1747229310350" TEXT="理解主要作用，副作用。&amp;lt;br&amp;gt;优先级和结合性对于我们读懂一个表达式，至关重要。&amp;lt;br&amp;gt;换句话说，如果不懂这些，有些表达式是看不懂的"><node CREATED="1747229310350" ID="ID_b2482fec8941483b" MODIFIED="1747229310350" TEXT="程序员不要自己为难自己"></node><node CREATED="1747229310350" ID="ID_713bd378319c3e5d" MODIFIED="1747229310350" TEXT="自己写代码的时候直接使用()。&amp;nbsp;&amp;lt;br&amp;gt;不要使用这种很复杂的优先级和结合性。&amp;nbsp;"></node></node></node><node CREATED="1747229310350" ID="ID_149fd9a1beca4988" POSITION="right" MODIFIED="1747229310350" TEXT="位运算符"><node CREATED="1747229310350" ID="ID_74adb8a6855a3486" MODIFIED="1747229310350" TEXT="移位运算"><node CREATED="1747229310350" ID="ID_a60735ea0711f89d" MODIFIED="1747229310350" TEXT="&amp;lt;&amp;lt; :&amp;nbsp;左移。就是将表达的二进制数整体往左挪动n位。&amp;lt;br&amp;gt;a &amp;lt;&amp;lt; b：将a表示的二进制数，整体挪b位，低位填0"></node><node CREATED="1747229310350" ID="ID_cd70a0d592944acf" MODIFIED="1747229310350" TEXT="&amp;gt;&amp;gt;：&amp;nbsp;右移。 C中无符号数直接逻辑右移。&amp;nbsp;有符号数，取决于编译器实现"></node></node><node CREATED="1747229310350" ID="ID_19521243aa40fb64" MODIFIED="1747229310350" TEXT="按位运算符"><node CREATED="1747229310350" ID="ID_27b9dfaf8e23b32c" MODIFIED="1747229310350" TEXT="按位取反~：&amp;nbsp;将二进制数，每一位都取反"></node><node CREATED="1747229310350" ID="ID_665fb2a82b062d1b" MODIFIED="1747229310350" TEXT="按位与&amp;amp;"></node><node CREATED="1747229310350" ID="ID_94f79bce01bbd1a8" MODIFIED="1747229310350" TEXT="按位异或^"></node><node CREATED="1747229310350" ID="ID_1ff8cb588ef3fe95" MODIFIED="1747229310350" TEXT="按位或|"></node></node><node CREATED="1747229310350" ID="ID_d369282c3106a330" MODIFIED="1747229310350" TEXT="面试题"><node CREATED="1747229310350" ID="ID_fe157cb029588d07" MODIFIED="1747229310350" TEXT="int find_last_set_bit(int n) {&amp;lt;br&amp;gt;&amp;nbsp; &amp;nbsp; return n &amp;amp; (-n);&amp;lt;br&amp;gt;}&amp;lt;br&amp;gt;上述的代码是在求一个叫做LSB的玩意。我现在的问题是&amp;lt;br&amp;gt;1.首先，帮我解释一下什么是LSB。&amp;nbsp;用小白的话说，不要搞非常专业的术语，目的就是越简单听懂越好&amp;lt;br&amp;gt;2.帮我解释一下这个代码是什么意思。最好举一个例子说明。一步一步分析，最后为什么得出了结论&amp;lt;br&amp;gt;"></node><node CREATED="1747229310350" ID="ID_a2bce4a44bda6ff1" MODIFIED="1747229310350" TEXT="怎么问GPT的话"><node CREATED="1747229310350" ID="ID_b5ecd6b6d53f19db" MODIFIED="1747229310350" TEXT="1.清晰的描述出你想要什么"></node><node CREATED="1747229310350" ID="ID_dff36c37cd89b41f" MODIFIED="1747229310350" TEXT="2.不断的迭代。（不断的改进）"></node><node CREATED="1747229310350" ID="ID_f49116aa45288cc8" MODIFIED="1747229310350" TEXT="3.可以告诉它具体的思路。"></node></node><node CREATED="1747229310350" ID="ID_e13dfcb8fe18286e" MODIFIED="1747229310350" TEXT="a^a = 0"></node></node></node></node></map>